mapper.select:
SELECT
${page.fields}
FROM (SELECT SUM(CASE WHEN PZ.ACTIVE_SYS = 4 THEN SUM ELSE 0 END) ASUM, SUM(CASE WHEN PZ.ACTIVE_SYS = 2 THEN SUM ELSE 0 END) BSUM, PZ.REPORT_TIME, PZ.CFG_ID, PZ.SERVICE FROM DF_PZ_REPORT PZ GROUP BY PZ.CFG_ID, PZ.SERVICE, PZ.REPORT_TIME ) DF_PZ_REPORT
AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
AND CFG_ID =#{searchCfgId}
AND SERVICE =#{searchService}
ORDER BY ${page.orderBy}

SELECT
${page.fields}
ASUM,BSUM,absum,REPORT_TIME,ATTR_TYPE,SERVICE
FROM ( SELECT attr_type,REPORT_TIME, sum(asum) asum, sum(bsum) bsum, SUM(absum) absum,service FROM (select attr_type, asum, bsum, absum, REPORT_TIME,service from (select attr_type, REPORT_TIME,service, asum, bsum, decode(asum, 0, bsum, asum) absum from (SELECT SUM(CASE WHEN PZ.ACTIVE_SYS = 4 THEN SUM ELSE 0 END) ASUM, SUM(CASE WHEN PZ.ACTIVE_SYS = 2 THEN SUM ELSE 0 END) BSUM,
PZ.REPORT_TIME, pz.cfg_id, pz.attr_type,pz.service FROM df_pz_attr_report PZ
AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
AND ATTR_TYPE =#{searchAttrType}
AND SERVICE =#{searchService}
GROUP BY pz.cfg_id, pz.attr_type, PZ.REPORT_TIME,pz.service)) a) group by attr_type, REPORT_TIME,service ) df_pz_attr_report
ORDER BY ${page.orderBy}

SELECT

	
		${page.fields}
	
	
		ASUM,BSUM,REPORT_TIME,SERVICE,SRC_PROVINCE,SRC_CITY
	

FROM (SELECT
SUM(CASE WHEN PZ.ACTIVE_SYS = 4 THEN SUM ELSE 0 END) ASUM,
SUM(CASE WHEN PZ.ACTIVE_SYS = 2 THEN SUM ELSE 0 END) BSUM,
PZ.REPORT_TIME,
PZ.SERVICE,
pz.SRC_PROVINCE,pz.SRC_CITY
FROM
DF_SRCIP_DOMESTIC_REPORT PZ
GROUP BY PZ.SRC_PROVINCE,pz.SRC_CITY,
PZ.SERVICE, PZ.REPORT_TIME
) DF_SRCIP_DOMESTIC_REPORT

	
		AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
	
	
		AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
	
	
		AND SRC_PROVINCE =#{searchSrcProvince}
	
	
		AND SRC_CITY =#{searchSrcCity}
	
	
		AND SERVICE =#{searchService}
	


	
		ORDER BY ${page.orderBy}

SELECT
${page.fields}
ASUM,BSUM,REPORT_TIME,DEST_COUNTRY,SERVICE
FROM (SELECT SUM(CASE WHEN PZ.ACTIVE_SYS = 4 THEN SUM ELSE 0 END) ASUM, SUM(CASE WHEN PZ.ACTIVE_SYS = 2 THEN SUM ELSE 0 END) BSUM, PZ.REPORT_TIME, PZ.SERVICE, pz.DEST_COUNTRY FROM DF_DESTIP_COUNTRY_REPORT PZ GROUP BY PZ.DEST_COUNTRY, PZ.SERVICE, PZ.REPORT_TIME ) DF_DESTIP_COUNTRY_REPORT
AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
AND DEST_COUNTRY =#{searchDestCountry}
AND SERVICE =#{searchService}
ORDER BY ${page.orderBy}

SELECT
${page.fields}
ASUM,BSUM,ABSUM,SERVICE
FROM (SELECT SUM(CASE WHEN PZ.ACTIVE_SYS = 4 THEN SUM ELSE 0 END) ASUM, SUM(CASE WHEN PZ.ACTIVE_SYS = 2 THEN SUM ELSE 0 END) BSUM, SUM(CASE WHEN PZ.ACTIVE_SYS = 4 OR PZ.CFG_ID IN (SELECT DISTINCT CFG_ID FROM DF_PZ_REPORT T WHERE T.ACTIVE_SYS = 2 AND T.CFG_ID NOT IN (SELECT CFG_ID FROM DF_PZ_REPORT B WHERE B.ACTIVE_SYS = 4)) THEN SUM ELSE 0 END) ABSUM, PZ.SERVICE FROM DF_PZ_REPORT PZ GROUP BY PZ.SERVICE ) DF_PZ_REPORT
AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
AND SERVICE =#{searchService}
ORDER BY ${page.orderBy}

SELECT
${page.fields}
CFG_ID,SERVICE,SUM
FROM (
SELECT CFG_ID,SERVICE, DECODE(ASUM,0,BSUM,ASUM) SUM FROM ( SELECT config_id CFG_ID, SERVICE, SUM(CASE WHEN ACTIVE_SYS=4 THEN SUM ELSE 0 END) ASUM, SUM(CASE WHEN ACTIVE_SYS=2 THEN SUM ELSE 0 END) BSUM FROM df_stat_log_hour
AND stat_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND stat_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
AND SERVICE =#{searchService}
GROUP BY config_id,SERVICE ) REPORT
SELECT config_id cfg_id,SERVICE,SUM(sum) SUM FROM df_stat_log_hour
AND stat_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND stat_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
AND SERVICE =#{searchService}
AND active_sys=#{searchStatActiveSys}
GROUP BY config_id,SERVICE
)
ORDER BY ${page.orderBy}

SELECT
${page.fields}
CFG_ID,SERVICE,SUM
FROM (
SELECT CFG_ID,SERVICE, DECODE(ASUM,0,BSUM,ASUM) SUM FROM ( SELECT CFG_ID, SERVICE, SUM(CASE WHEN ACTIVE_SYS=4 THEN SUM ELSE 0 END) ASUM, SUM(CASE WHEN ACTIVE_SYS=2 THEN SUM ELSE 0 END) BSUM FROM DF_PZ_REPORT
AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
AND SERVICE =#{searchService}
GROUP BY CFG_ID,SERVICE ) REPORT
SELECT CFG_ID,SERVICE,SUM(sum) SUM FROM DF_PZ_REPORT
AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
AND SERVICE =#{searchService}
AND active_sys=#{searchStatActiveSys}
GROUP BY CFG_ID,SERVICE
)
ORDER BY ${page.orderBy}

SELECT SUM(sum) SUM FROM DF_PZ_REPORT
AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
AND SERVICE =#{searchService}
AND active_sys=#{searchStatActiveSys}

SELECT
${page.fields}
FROM (SELECT SUM(CASE WHEN PZ.ACTIVE_SYS = 4 THEN SUM ELSE 0 END) ASUM, SUM(CASE WHEN PZ.ACTIVE_SYS = 2 THEN SUM ELSE 0 END) BSUM, SUM(CASE WHEN PZ.ACTIVE_SYS = 1 THEN SUM ELSE 0 END) CSUM, PZ.REPORT_TIME, PZ.SERVICE FROM DF_SERVICE_REPORT PZ GROUP BY PZ.SERVICE, PZ.REPORT_TIME ) DF_SERVICE_REPORT
AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
and service=#{searchService}
ORDER BY ${page.orderBy}

SELECT
${page.fields}
ASUM,BSUM,REPORT_TIME,SERVICE,LWHH
FROM (SELECT SUM(CASE WHEN PZ.ACTIVE_SYS = 4 THEN SUM ELSE 0 END) ASUM, SUM(CASE WHEN PZ.ACTIVE_SYS = 2 THEN SUM ELSE 0 END) BSUM, PZ.REPORT_TIME, PZ.lwhh,pz.service FROM DF_LWHH_REPORT PZ GROUP BY PZ.lwhh,pz.service, PZ.REPORT_TIME ) DF_LWHH_REPORT
AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
AND service=#{searchService}
AND lwhh=#{searchLwhh}
ORDER BY ${page.orderBy}

SELECT
${page.fields}
ASUM,BSUM,REPORT_TIME,SERVICE,ENTRANCE_ID
FROM (SELECT SUM(CASE WHEN PZ.ACTIVE_SYS = 4 THEN SUM ELSE 0 END) ASUM, SUM(CASE WHEN PZ.ACTIVE_SYS = 2 THEN SUM ELSE 0 END) BSUM, PZ.REPORT_TIME, PZ.ENTRANCE_ID,pz.service FROM DF_ENTRANCE_REPORT PZ GROUP BY PZ.ENTRANCE_ID,pz.service, PZ.REPORT_TIME ) DF_LWHH_REPORT
AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
AND service=#{searchService}
AND ENTRANCE_ID=#{searchEntraceId}
ORDER BY ${page.orderBy}

SELECT
${page.fields}
FROM (SELECT SUM(CASE WHEN t.ACTIVE_SYS = 4 THEN SUM ELSE 0 END) ASUM, SUM(CASE WHEN t.ACTIVE_SYS = 2 THEN SUM ELSE 0 END) BSUM, SUM(CASE WHEN t.ACTIVE_SYS = 1 THEN SUM ELSE 0 END) CSUM, t.SRC_PROVINCE, t.SRC_CITY , t.REPORT_TIME FROM DF_SRCIP_DOMESTIC_REPORT t GROUP BY t.SRC_PROVINCE, t.SRC_CITY, t.REPORT_TIME ) DF_SRCIP_DOMESTIC_REPORT
AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
ORDER BY ${page.orderBy}

SELECT
${page.fields}
FROM (SELECT SUM(CASE WHEN t.ACTIVE_SYS = 4 THEN SUM ELSE 0 END) ASUM, SUM(CASE WHEN t.ACTIVE_SYS = 2 THEN SUM ELSE 0 END) BSUM, SUM(CASE WHEN t.ACTIVE_SYS = 1 THEN SUM ELSE 0 END) CSUM, t.DEST_COUNTRY , t.REPORT_TIME FROM DF_DESTIP_COUNTRY_REPORT t GROUP BY t.DEST_COUNTRY, t.REPORT_TIME ) DF_DESTIP_COUNTRY_REPORT
AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
ORDER BY ${page.orderBy}
